'use client';
import { useState, useEffect } from 'react';

export default function PixelAgent() {
  const [logs, setLogs] = useState<string[]>([]);
  const [status, setStatus] = useState('idle');

  useEffect(() => {
    const fetchStatus = async () => {
      try {
        const res = await fetch('/api/status');
        const data = await res.json();
        
        setStatus(data.status);
        
        setLogs(prev => {
          // เช็คก่อนว่าข้อความใหม่ซ้ำกับบรรทัดล่าสุดไหม ถ้าไม่ซ้ำค่อยเพิ่ม
          if (prev.length === 0 || prev[prev.length - 1] !== data.task) {
            const newLogs = [...prev, data.task];
            return newLogs.slice(-5); // เก็บไว้โชว์แค่ 5 บรรทัดล่าสุด
          }
          return prev;
        });
      } catch (error) {
        console.error('Error fetching agent status:', error);
      }
    };

    const interval = setInterval(fetchStatus, 1000);
    return () => clearInterval(interval);
  }, []);

  // เลือกภาพตุ๊กตาตามสถานะ
  const avatarUrl = status === 'working' 
    ? 'https://raw.githubusercontent.com/Tarikul-Islam-Anik/Animated-Fluent-Emojis/master/Emojis/People/Man%20Technologist.png'
    : status === 'success'
    ? 'https://raw.githubusercontent.com/Tarikul-Islam-Anik/Animated-Fluent-Emojis/master/Emojis/Smilies/Partying%20Face.png'
    : 'https://raw.githubusercontent.com/Tarikul-Islam-Anik/Animated-Fluent-Emojis/master/Emojis/Smilies/Sleeping%20Face.png';

  return (
    <div className="fixed bottom-6 right-6 z-50 flex items-end gap-4 font-sans">
      {/* กล่อง Workflow สไตล์ Glassmorphism */}
      <div className="bg-gray-900/80 backdrop-blur-md border border-white/10 rounded-2xl p-4 shadow-2xl w-80">
        <div className="flex items-center gap-2 mb-3 border-b border-white/10 pb-2">
          <span className="text-yellow-400">⚡</span>
          <h3 className="text-white font-semibold text-sm tracking-wide">Agent Workflow</h3>
          <div className="ml-auto w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
        </div>
        <div className="flex flex-col gap-1">
          {logs.map((log, idx) => (
            <p 
              key={idx} 
              className={`text-sm transition-all duration-300 ${
                idx === logs.length - 1 ? 'text-white' : 'text-gray-400'
              }`}
            >
              <span className="text-gray-500 mr-2">{'>'}</span>{log}
            </p>
          ))}
          {logs.length === 0 && <p className="text-gray-500 text-sm italic">รอรับคำสั่ง...</p>}
        </div>
      </div>

      {/* ภาพ Avatar พร้อมแอนิเมชัน */}
      <div className={`w-20 h-20 drop-shadow-xl ${status === 'working' ? 'animate-bounce' : ''}`}> 
        <img src={avatarUrl} alt="Pixel Agent" className="w-full h-full object-contain" />
      </div>
    </div>
  );
}